DELETE FROM doc_no_sequences WHERE tenant_id=tid;


-- Reset all sequences to max(id)+1 after explicit-id inserts
DO $reset$ DECLARE r record; mx bigint; BEGIN
  FOR r IN SELECT table_name, column_name, pg_get_serial_sequence(format('%I', table_name), column_name) AS seq
           FROM information_schema.columns WHERE table_schema='public' AND column_default LIKE 'nextval%' AND is_identity='NO'
  LOOP
    EXECUTE format('SELECT COALESCE(max(%I),0) FROM %I', r.column_name, r.table_name) INTO mx;
    IF mx > 0 THEN EXECUTE format('SELECT setval(%L, %s, true)', r.seq, mx); END IF;
  END LOOP;
END $reset$;

RAISE NOTICE 'ALL DATA SEED DONE';
END $$;
COMMIT;

